import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ArrowLeft } from 'lucide-react';
import './index.css';

const mockPatients = [
  { id: 'P001', name: 'Wang Xiao Ming', na: 128, k: 4.5, status: 'Critical' },
  { id: 'P002', name: 'Li Da Tong', na: 138, k: 4.2, status: 'Observing' }
];

const mockLabData = [{ date: '9/14', na: 140, k: 3.8 }, { date: '9/15', na: 138, k: 4.0 }, { date: '9/16', na: 136, k: 4.6 }];

export default function App() {
  const [view, setView] = useState('overview');
  const [selectedPatient, setSelectedPatient] = useState(null);

  if (view === 'dashboard') {
    return (
      <div className="p-8 bg-slate-50 min-h-screen">
        <button onClick={() => setView('overview')} className="text-blue-600 mb-4 font-bold flex items-center">BACK</button>
        <div className="bg-white p-10 rounded-[3rem] shadow-xl border">
          <h1 className="text-3xl font-black mb-8 italic">{selectedPatient?.name} Dashboard</h1>
          <div className="h-64 w-full mb-10">
            <ResponsiveContainer>
              <LineChart data={mockLabData}>
                <XAxis dataKey="date" />
                <YAxis yAxisId="l" domain={[120, 160]} />
                <YAxis yAxisId="r" orientation="right" domain={[2, 8]} />
                <Tooltip />
                <Line yAxisId="l" dataKey="na" stroke="#f97316" strokeWidth={4} />
                <Line yAxisId="r" dataKey="k" stroke="#6366f1" strokeWidth={4} />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div className="bg-rose-50 p-6 rounded-2xl border border-rose-100 font-bold text-rose-600 text-center">
            ADR Analysis: Highly Correlated (Na 138 to 128)
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-10 bg-slate-100 min-h-screen">
      <h2 className="text-2xl font-black mb-6 border-b-4 border-blue-600 w-fit pb-1 italic">PATIENT RECORDS</h2>
      <div className="bg-white rounded-3xl shadow-xl overflow-hidden border">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-400 text-xs font-bold uppercase">
            <tr><th className="p-4">ID</th><th className="p-4">Patient</th><th className="p-4">Na / K</th><th className="p-4">Status</th></tr>
          </thead>
          <tbody>
            {mockPatients.map(p => (
              <tr key={p.id} onClick={() => { setSelectedPatient(p); setView('dashboard'); }} className="border-t hover:bg-blue-50 cursor-pointer transition-colors">
                <td className="p-4 font-bold text-blue-600">{p.id}</td>
                <td className="p-4 font-bold">{p.name}</td>
                <td className="p-4">{p.na} / {p.k}</td>
                <td className="p-4"><span className="bg-rose-100 text-rose-600 px-3 py-1 rounded-full text-xs font-bold">{p.status}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
